        /// <summary>
        /// Capability contains the container capabilities to add or drop
        /// Dropping a capability will drop it from all sets.
        /// If a capability is added to only the add_capabilities list then it gets added to permitted,
        /// inheritable, effective and bounding sets, i.e. all sets except the ambient set.
        /// If a capability is added to only the add_ambient_capabilities list then it gets added to all sets, i.e
        /// permitted
        /// inheritable, effective, bounding and ambient sets.
        /// If a capability is added to add_capabilities and add_ambient_capabilities lists then it gets added to all
        /// sets, i.e.
        /// permitted, inheritable, effective, bounding and ambient sets.
        /// </summary>
        public class Capability {
            /// <summary>List of capabilities to add.</summary>
            string[,,] add_capabilities;

            /// <summary>List of capabilities to drop.</summary>
            string[,,] drop_capabilities;

            /// <summary>List of ambient capabilities to add.</summary>
            string[,,] add_ambient_capabilities;
        }

        /// <summary>LinuxContainerSecurityContext holds linux security configuration that will be applied to a container.</summary>
        public class LinuxContainerSecurityContext {
            /// <summary>Capabilities to add or drop.</summary>
            Capability capabilities;

            /// <summary>
            /// If set, run container in privileged mode.
            /// Privileged mode is incompatible with the following options. If
            /// privileged is set, the following features MAY have no effect:
            /// 1. capabilities
            /// 2. selinux_options
            /// 4. seccomp
            /// 5. apparmor
            ///
            /// Privileged mode implies the following specific options are applied:
            /// 1. All capabilities are added.
            /// 2. Sensitive paths, such as kernel module paths within sysfs, are not masked.
            /// 3. Any sysfs and procfs mounts are mounted RW.
            /// 4. AppArmor confinement is not applied.
            /// 5. Seccomp restrictions are not applied.
            /// 6. The device cgroup does not restrict access to any devices.
            /// 7. All devices from the host's /dev are available within the container.
            /// 8. SELinux restrictions are not applied (e.g. label=disabled).
            /// </summary>
            bool privileged;

            /// <summary>
            /// Configurations for the container's namespaces.
            /// Only used if the container uses namespace for isolation.
            /// </summary>
            NamespaceOption namespace_options;

            /// <summary>SELinux context to be optionally applied.</summary>
            SELinuxOption selinux_options;

            /// <summary>
            /// UID to run the container process as. Only one of run_as_user and
            /// run_as_username can be specified at a time.
            /// </summary>
            Int64Value run_as_user;

            /// <summary>
            /// GID to run the container process as. run_as_group should only be specified
            /// when run_as_user or run_as_username is specified; otherwise, the runtime
            /// MUST error.
            /// </summary>
            Int64Value run_as_group;

            /// <summary>
            /// User name to run the container process as. If specified, the user MUST
            /// exist in the container image (i.e. in the /etc/passwd inside the image),
            /// and be resolved there by the runtime; otherwise, the runtime MUST error.
            /// </summary>
            string run_as_username;

            /// <summary>If set, the root filesystem of the container is read-only.</summary>
            bool readonly_rootfs;

            /// <summary>
            /// List of groups applied to the first process run in each container.
            /// supplemental_groups_policy can control how groups will be calculated.
            /// </summary>
            [X] long[,,] supplemental_groups;

            /// <summary>
            /// supplemental_groups_policy defines how supplemental groups of the first
            /// container processes are calculated.
            /// Valid values are "Merge" and "Strict".
            /// If not specified, "Merge" is used.
            /// </summary>
            SupplementalGroupsPolicy supplemental_groups_policy;

            /// <summary>
            /// no_new_privs defines if the flag for no_new_privs should be set on the
            /// container.
            /// </summary>
            bool no_new_privs;

            /// <summary>
            /// masked_paths is a slice of paths that should be masked by the container
            /// runtime, this can be passed directly to the OCI spec.
            /// </summary>
            string[,,] masked_paths;

            /// <summary>
            /// readonly_paths is a slice of paths that should be set as readonly by the
            /// container runtime, this can be passed directly to the OCI spec.
            /// </summary>
            string[,,] readonly_paths;

            /// <summary>Seccomp profile for the container.</summary>
            SecurityProfile seccomp;

            /// <summary>AppArmor profile for the container.</summary>
            SecurityProfile apparmor;

            /// <summary>
            /// AppArmor profile for the container, candidate values are:
            ///   - runtime/default: equivalent to not specifying a profile.
            ///   - unconfined: no profiles are loaded
            ///   - localhost/&lt;profile_name>: profile loaded on the node
            ///     (localhost) by name. The possible profile names are detailed at
            ///     https://gitlab.com/apparmor/apparmor/-/wikis/AppArmor_Core_Policy_Reference
            /// </summary>
            [Obsolete]
            string apparmor_profile;

            /// <summary>
            /// Seccomp profile for the container, candidate values are:
            ///   - runtime/default: the default profile for the container runtime
            ///   - unconfined: unconfined profile, ie, no seccomp sandboxing
            ///   - localhost/&lt;full-path-to-profile>: the profile installed on the node.
            ///     &lt;full-path-to-profile> is the full path of the profile.
            ///
            /// Default: "", which is identical with unconfined.
            /// </summary>
            [Obsolete]
            string seccomp_profile_path;
        }

